import java.util.Scanner;
import java.math.BigInteger;

public class Main {
    // Function to compute factorial of a number
    public static BigInteger factorial(int n) {
        BigInteger result = BigInteger.ONE;
        for (int i = 2; i <= n; i++) {
            result = result.multiply(BigInteger.valueOf(i));
        }
        return result;
    }

    // Function to compute A(n, k) = n! / (n - k)!
    public static BigInteger A(int n, int k) {
        return factorial(n).divide(factorial(n - k));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int mod = sc.nextInt();

        if (n == 1) {
            System.out.println(0);
            sc.close();
            return;
        }

        int[] z = new int[1];
        z[0] = 1;
        long total = 0;

        for (int i = 2; i <= n; i++) {
            int size = ((i - 1) * i) / 2 + 1;
            int[] new_z = new int[size];

            int[] d = new int[z.length + 1];
            for (int w = z.length - 1; w >= 0; w--) {
                d[w] = (int)(( (long)d[w + 1] + z[w]) % mod);
            }

            for (int w = 0; w < size; w++) {
                int L = Math.max(0, w + 1 - i);
                int R = Math.min(z.length - 1, w);
                int val = d[L] - d[R + 1];
                new_z[w] = ((val % mod) + mod) % mod; // ensure non-negative
            }

            int[] e = new int[d.length];
            int[] f = new int[d.length];

            for (int w = 0; w < d.length - 1; w++) {
                e[w + 1] = (int)(( (long)e[w] + d[w]) % mod);
                f[w + 1] = (int)(( (long)f[w] - (long)w * d[w]) % mod);
            }

            int R = z.length;
            long bbb = 0;

            int start1 = Math.max(0, z.length - i);
            int end1 = z.length - 1;
            for (int jj = start1; jj < end1; jj++) {
                int L = jj + 2;
                long temp = (( (long)(e[R] - e[L]) * (i + 1 + jj) ) + (f[R] - f[L])) % mod;
                temp = (temp + mod) % mod;
                bbb += (temp * z[jj]) % mod;
            }

            int start2 = 0;
            int end2 = z.length - i;
            for (int jj = start2; jj < end2; jj++) {
                int L = jj + 2;
                int R2 = i + jj;
                long temp = (( (long)(e[R2 + 1] - e[L]) * (i + 1 + jj) ) + (f[R2 + 1] - f[L])) % mod;
                temp = (temp + mod) % mod;
                bbb += (temp * z[jj]) % mod;
            }

            total = (total + (bbb % mod) * A(n, n - i).longValue()) % mod;
            z = new_z;
        }

        System.out.println(total % mod);
        sc.close();
    }
}
